package com.franco.desco.domain.visit;import java.math.BigDecimal;import java.time.Instant;import java.util.List;
public final class VisitModels{private VisitModels(){}public record Summary(Long visitaTecnicaId,Long salidaParticipanteId,Long salidaCampoId,Long empleadoId,String tecnico,Long predioId,String codigoPredio,String predio,Instant fechaHoraInicio,Instant fechaHoraFin,String objetivo,String estadoProceso,BigDecimal latitud,BigDecimal longitud){}public record Evaluation(Long evaluacionAgronomicaId,Long parcelaCultivoId,Integer tipoEvaluacionId,String codigoTipoEvaluacion,String tipoEvaluacion,Instant fechaHora,String resultado,String observacion,BigDecimal porcentajeMateriaSeca,Integer numeroMuestras){}public record File(Long archivoId,String nombreOriginal,String mimeType,Long tamanoBytes,String secureUrl,String categoria,String origenCaptura,Instant fechaCarga){}public record Detail(Summary visita,String resumen,String recomendaciones,List<Evaluation>evaluaciones,List<File>archivos){public Detail{evaluaciones=evaluaciones==null?List.of():List.copyOf(evaluaciones);archivos=archivos==null?List.of():List.copyOf(archivos);}}}
